const e={meta:{title:"POP · Студия для авторов Fortnite"},nav:{features:"Возможности",boussole:"Boussole",pricing:"Тарифы",faq:"Вопросы",login:"Войти",join:"В бету",home:"POP, главная",lang:"Язык",search:"Найти страну"},hero:{announce:"Новое: Boussole, встроенный ассистент",h1a:"Ваши карты Fortnite.",h1b:"Вместе. Без хаоса.",subA:"POP собирает всю вашу студию UEFN в одном месте: ",subB:"задачи на час",subC:", Verse, связанный с UEFN, доска, анализ рынка и раздел доходов.",cta:"Встать в лист ожидания",see:"Смотреть возможности",micro1:"Закрытая бета",micro2:"Доступ по листу ожидания",micro3:"Связан с UEFN"},marquee:{label:"Работает с вашими инструментами",epic:"API Fortnite от Epic"},pain:{eyebrow:"Проблема",h2a:"Discord, три Google Docs,",h2b:"и никто не знает, кто что делает.",without:"Без POP",with:"С POP",bad:["«Кто трогал спавнер?»","Verse гуляет по Discord в .txt","Список задач в Google Doc","Таблица доходов, версия 7","«Так когда мы выходим?»","Строим, не зная, работает ли жанр"],good:["Каждое действие записано и отменяемо","Ctrl+S отправляет Verse в UEFN","Задачи на час, с зависимостями","Понятная выписка для каждого","Boussole следит за этапами и задержками","Вердикт по жанру на реальных цифрах"]},feat:{eyebrow:"Возможности",h2:"Вся студия, от идеи до релиза.",p:"Здесь показаны настоящие экраны POP, только проще.",items:[{tag:"Задачи и Boussole",h:"Задачи на час. Ассистент каждое утро.",p:"Генератор делит карту на задачи на час с зависимостями. Boussole подводит итог дня, отмечает задержки и подсказывает, с чего начать.",pts:["Канбан и зависимости","Задержки и этапы под контролем","«Взять» в один клик"]},{tag:"Редактор Verse",h:"Ctrl+S — и это уже в UEFN.",p:"Verse пишется в POP и сразу попадает в проект: компиляция, ошибки в нужной строке, тестовая сессия. Ассистент объясняет и исправляет без внешних сервисов.",pts:["Компиляция в UEFN","Ошибки по строкам","Предложенные исправления"]},{tag:"Органайзер",h:"Все устройства. Разложены за три секунды.",p:"Ищите по тегу, типу или папке, выделите двадцать и переименуйте, переместите или дублируйте разом. Ctrl+Z отменяет. Если UEFN закрыт, изменения подождут.",pts:["Поиск tag:, type:, папка:","Массовые правки","Всё можно отменить"]},{tag:"Доска",h:"Рисуйте карту вместе.",p:"Стикеры, фигуры, стрелки, цвета, жирный, подчёркнутый: всё, чтобы разложить идеи. Голосуйте и превращайте лучшие стикеры в задачи.",pts:["Полное форматирование","Совместно в реальном времени","Стикеры → задачи"]},{tag:"Аналитика",h:"Знайте, что строить, до того как строить.",p:"Какие жанры привлекают игроков, где есть место, какие карты взлетают на старте и что в тренде на видео. Данные из официального API Epic.",pts:["Вердикт по жанру","Карты, которые работают","Тренды TikTok и Shorts"]},{tag:"Выплаты",h:"Каждый знает, сколько получает.",p:"Правила раздела в процентах, фиксированной суммой или за задачу, импорт доходов, выписка на каждого. Больше никаких таблиц, потерянных в Discord.",pts:["Процент, фикс, за задачу","Импорт CSV","Выписка для каждого"]}],aiB:"Уже пользуетесь ИИ?",aiText:"Подключите Claude, Cursor, Codex или другой ИИ с поддержкой MCP: он берёт задачу, пишет Verse, компилирует и закрывает задачу с заметкой. Каждое действие записано и отменяемо."},bou:{eyebrow:"Встроенный ассистент",h2a:"Задайте вопрос.",h2b:"Boussole ответит.",p:"Boussole знает ваши задачи, этапы и команду. Он говорит, что просрочено, кто над чем работает и с чего начать, и шаг за шагом ведёт новичков по POP. Ваши данные не покидают POP.",sub:"встроенный ассистент",ask:"Как мне…?",demo:[{q:"Что мне делать сейчас?",a:["**Привет, Léa, наверстаем?**","[r] 2 задачи просрочены.","[g] Вчера вы завершили 3 задачи.","Сейчас: **#42 Система очков**, она разблокирует ещё 3 задачи."]},{q:"Как подключить UEFN?",a:["**Как подключить UEFN к POP?**","1. Органайзер → Скачать UEFN Link.","2. Дважды щёлкните pop-link.exe на ПК.","3. В UEFN: Model Context Protocol → Start Server."]},{q:"Мы успеваем к бете?",a:["[o] Этап «Бета» через 5 дней: осталось 9 задач.","При текущем темпе (1,5 в день) понадобится 6 дней. **Ожидаемая задержка: 1 день.**"]},{q:"Над чем работает Hugo?",a:["У **Hugo** 1 задача в работе и 2 в очереди:","• **#38** Декор зоны 2 · в работе со вчера","• **#44** Финальный экран · ждёт #42","[g] 4 задачи завершены на этой неделе."]},{q:"Мой ИИ может закрывать задачи?",a:["Да: после подключения в «Подключённые ИИ» он использует **next_task**, **set_task_status** и **comment_task**. Каждое действие помечено «ИИ» в истории."]}]},stats:[["1 ч","на задачу, чтобы двигаться каждый день"],["0","обязательных внешних ИИ-сервисов"],["7 дней","статистики по карте из API Epic"],["100%","действий в UEFN можно отменить"]],pricing:{eyebrow:"Тарифы",h2:"Выберите тариф.",p:"POP в закрытой бете: доступ по листу ожидания. Цены действуют с запуска, и мы предупредим вас перед любым платежом.",perMonth:"/ мес.",compare:"Сравнить тарифы",unlimited:"Без ограничений",soon:"Скоро",plans:[{name:"Автор",tag:"Для старта",desc:"Одна карта, небольшая команда, всё самое нужное.",cta:"Встать в лист"},{name:"Studio",tag:"Самый полный",desc:"Для студий, которые выпускают карты командой.",cta:"Встать в лист"},{name:"Studio+",tag:"Скоро",desc:"Всё из Studio плюс POP Forge: настольное приложение, которое строит в UEFN.",cta:"Встать в лист"}],rows:["Организация","Задачи на час, канбан, зависимости","Boussole, встроенный ассистент","Страницы, доска, планирование и этапы","Карты","Участники","UEFN","UEFN Link: синхронизированные проекты","Связанный редактор Verse (компиляция, ошибки по строкам)","Органайзер акторов и массовые правки","Подключённые ИИ (Claude, Cursor, Codex…)","POP Forge: помощь в строительстве в UEFN","Рост","Анализ рынка и успешные карты","Видеотренды TikTok и YouTube Shorts","Обмен плейтестами и день релиза","Раздел доходов и выписки","Discord, GitHub, Lore"]},faq:{eyebrow:"Вопросы",h2:"Что нас спрашивают.",items:[["Нужен ли ПК с Windows?","Для связи с UEFN — да: UEFN работает только на Windows, и UEFN Link запускается на этом ПК. Остальной POP работает в любом браузере, включая Mac."],["POP публикует мою карту?","Нет. POP готовит всё (проверка перед публикацией, плейтесты, план дня релиза), но публикация всегда проходит в портале авторов Epic."],["Как работает ассистент Boussole?","Boussole встроен в POP: он читает ваши задачи, их сроки, зависимости и этапы, чтобы подвести итог дня, ответить на вопросы («что просрочено?», «над чем работает Hugo?») и объяснить, как пользоваться POP. Он работает целиком внутри POP: ваши данные не уходят ни в какой внешний сервис."],["А если я хочу использовать свой ИИ?","Подключите Claude, Cursor, Codex или другой ИИ с поддержкой MCP в «Подключённые ИИ». Он может читать и менять задачи, Verse и акторов UEFN, а каждое действие записано и отменяемо."],["Откуда цифры в аналитике?","Из официального API Fortnite от Epic: игроки, пик одновременных игроков, время игры и удержание для каждой публичной карты за 7 дней."],["Как получить доступ?","POP в закрытой бете. Встаньте в лист ожидания: мы рассматриваем заявки по одной, и вы получите по почте ссылку для создания аккаунта."],["Сколько это стоит?","Цены указаны выше. Они действуют с открытия POP; участников беты предупредят перед любым платежом."]]},final:{h2a:"Ваша следующая карта",h2b:"начинается здесь.",p:"Встаньте в лист ожидания: мы пришлём доступ, как только освободится место."},foot:{made:"Сделано авторами Fortnite для авторов Fortnite.",legal:"Fortnite и UEFN — товарные знаки Epic Games. POP не связан с Epic Games и не одобрен ею.",product:"Продукт",help:"Помощь",account:"Аккаунт"},mock:{overview:"Обзор",nav:["Обзор","Страницы","Доска","Задачи","Редактор Verse","Органайзер","Рынок"],hello:"Привет, Léa, предлагаю начать с #42.",late:"2 задачи просрочены (самая старая была на 12 нояб.).",mile:"Этап «Бета» через 5 дней: осталось 9 задач, ожидаемая задержка 1 день.",take:"Взять",start:"Начать",unlocks:"разблокирует ещё 3 задачи",today:"срок сегодня",waits:"ждёт #42",todo:"К выполнению",doing:"В работе",done:"Готово",tasks:["Система очков","Декор зоны 2","Финальный экран","Внутренний плейтест","Спавн игроков","Шторм"],sent:"отправлено в UEFN",err:"Строка 12: нельзя сложить int и float.",fix:"Исправить: Points += 1",red:"Красная команда",selected:"Выбрано: 2",rename:"Переименовать",move:"Переместить",dup:"Дублировать",s1:"Командный режим 4v4",s2a:"Финальный босс",s2b:"в центре",s3:"Экономика: 1 монета / устранение",verdicts:["Хорошая возможность","Популярно, но тесно","Перенасыщено","Ниша"],typical:"игроков / типичная карта",earnings:"Доход за октябрь",roles:["Код · 40%","Карта · 35%","Музыка · фикс","Остаток"],noTransfer:"POP считает, но никогда не переводит деньги."},wl:{eyebrow:"Закрытая бета",title:"Встать в лист ожидания",intro:"Мы открываем POP постепенно, чтобы помочь каждой студии. Расскажите о себе, и мы пришлём доступ как можно скорее.",pageIntro:"Аккаунты POP только по приглашению. Расскажите о себе: когда доступ одобрят, вы получите ссылку для создания аккаунта.",invalid:"Эта ссылка недействительна, уже использована или устарела. Отправьте заявку снова или напишите команде POP.",name:"Имя или ник",email:"E-mail",studio:"Студия",optional:"(необязательно)",studioPh:"Название студии",team:"Размер команды",teams:["Один","2–3","4–10","Больше 10"],exp:"Опыт",exps:["Новичок в UEFN","Несколько опубликованных карт","Опытный автор","Профессиональная студия"],links:"Ваши карты или соцсети",linksPh:"Коды островов, TikTok, YouTube…",msg:"Что вы хотите делать в POP",msgPh:"Например: нас 4 человека на tycoon-карте, и мы теряемся между Discord и Google Docs.",send:"Запросить доступ",sending:"Отправка…",nospam:"Без спама: пишем только чтобы выдать доступ.",okTitle:"Готово, спасибо!",okText:"Ваша заявка дошла до команды POP. Ссылку для создания аккаунта вы получите, как только освободится место.",alreadyTitle:"Вы уже в списке.",approvedTitle:"Ваш доступ уже одобрен.",approvedText:"Проверьте почту: ссылка для создания аккаунта отправлена. Если её нет, напишите нам.",close:"Закрыть"}};export{e as default};
